(4326116, 623843, 84124, '<td valign="top">Oh beautiful orion!  Nice capture, very well done.</td>', 'Oh beautiful orion!  Nice capture, very well done.', '2007-12-20 13:29:25.000000', NULL, 1),
(4326119, 622886, 84124, '<td valign="top">Beautiful shot, would score higher if you painted the foreground with some light.</td>', 'Beautiful shot, would score higher if you painted the foreground with some light.', '2007-12-20 13:30:12.000000', NULL, 1),
(4326124, 623620, 84124, '<td valign="top">Fabulous capture!  I''d score it higher but it looks like your focus is a bit soft.</td>', 'Fabulous capture!  I''d score it higher but it looks like your focus is a bit soft.', '2007-12-20 13:32:02.000000', NULL, 1),
(4326141, 622264, 84124, '<td valign="top">What a beautiful sky!  am scoring quite high, but could be even better if you provided some foreground illumination.</td>', 'What a beautiful sky!  am scoring quite high, but could be even better if you provided some foreground illumination.', '2007-12-20 13:35:18.000000', NULL, 1),
(4326158, 623277, 7786, '<td valign="top">Beautiful building and well captured.</td>', 'Beautiful building and well captured.', '2007-12-20 13:40:19.000000', NULL, 1),
(4326176, 623541, 19072, '<td valign="top">nice!  I think it would be better if you''d use a longer exposure.</td>', 'nice!  I think it would be better if you''d use a longer exposure.', '2007-12-20 13:47:48.000000', NULL, 1),
(4326204, 623796, 71526, '<td valign="top">Nice effect!</td>', 'Nice effect!', '2007-12-20 13:58:32.000000', NULL, 1),
(4326212, 623520, 71526, '<td valign="top">Great focus! Nice idea!</td>', 'Great focus! Nice idea!', '2007-12-20 14:01:41.000000', NULL, 1),
(4326215, 623557, 71526, '<td valign="top">Nice light effects!</td>', 'Nice light effects!', '2007-12-20 14:03:13.000000', NULL, 1),
(4326219, 623441, 19072, '<td valign="top">it would have been be perfect if you would captured the smoke, very nice anyway!</td>', 'it would have been be perfect if you would captured the smoke, very nice anyway!', '2007-12-20 14:06:19.000000', NULL, 1),
(4326226, 623481, 24846, '<td valign="top">Different perspective on the famous skyline. Nice work.</td>', 'Different perspective on the famous skyline. Nice work.', '2007-12-20 14:10:16.000000', NULL, 1),
(4326228, 623843, 24846, '<td valign="top">Nice composition. Good luck,</td>', 'Nice composition. Good luck,', '2007-12-20 14:12:01.000000', NULL, 1),
(4326230, 623029, 24846, '<td valign="top">-10- Happy Holidays</td>', '-10- Happy Holidays', '2007-12-20 14:13:08.000000', NULL, 1),
(4326232, 623500, 71526, '<td valign="top">yes... i agree with you, this seems Back to The Future II! :)</td>', 'yes... i agree with you, this seems Back to The Future II! :)', '2007-12-20 14:13:18.000000', NULL, 1),
(4326234, 623042, 71526, '<td valign="top">great shot, love the result of your long exposure.</td>', 'great shot, love the result of your long exposure.', '2007-12-20 14:14:14.000000', NULL, 1),
(4326238, 623460, 71526, '<td valign="top">Simply lovely!</td>', 'Simply lovely!', '2007-12-20 14:15:08.000000', NULL, 1),
(4326240, 623377, 71526, '<td valign="top">I like your abstract shot! Good work!</td>', 'I like your abstract shot! Good work!', '2007-12-20 14:15:38.000000', NULL, 1),
(4326252, 623785, 71526, '<td valign="top">Love the blues here!!!!!!</td>', 'Love the blues here!!!!!!', '2007-12-20 14:24:11.000000', NULL, 1),
(4326253, 623543, 61679, '<td valign="top">Back to comment:  The best skyline image in the challenge.  It looks like the color version of hotpasta''s November Free Study image.  I like this a whole lot better. Giving it a bump to a 9.</td>', 'Back to comment:  The best skyline image in the challenge.  It looks like the color version of hotpasta''s November Free Study image.  I like this a whole lot better. Giving it a bump to a 9.', '2007-12-20 14:24:35.000000', NULL, 1),
(4326290, 623048, 71526, '<td valign="top">Really nice night landscape.</td>', 'Really nice night landscape.', '2007-12-20 14:38:15.000000', NULL, 1),
(4326293, 622236, 71526, '<td valign="top">Really nice night landscape.</td>', 'Really nice night landscape.', '2007-12-20 14:38:28.000000', NULL, 1),
(4326296, 622635, 71526, '<td valign="top">Nice light effect at this explosive shot.</td>', 'Nice light effect at this explosive shot.', '2007-12-20 14:39:17.000000', NULL, 1),
(4326298, 623688, 71526, '<td valign="top">The water seems magic here. Good shot!</td>', 'The water seems magic here. Good shot!', '2007-12-20 14:40:14.000000', NULL, 1),
(4326300, 623775, 71526, '<td valign="top">Is this a dream? I think so!</td>', 'Is this a dream? I think so!', '2007-12-20 14:40:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4326303, 623839, 71526, '<td valign="top">wow! The light is lovely!</td>', 'wow! The light is lovely!', '2007-12-20 14:41:20.000000', NULL, 1),
(4326309, 622730, 71526, '<td valign="top">Love the lights here! Good work.</td>', 'Love the lights here! Good work.', '2007-12-20 14:45:04.000000', NULL, 1),
(4326312, 623029, 84124, '<td valign="top">You captured the bareness of the scene so well, congrats!  I''m giving it a good score but would have been higher if you either cropped the moon out or used a cutout to reduce the exposure time on it.  Regardless, this is one of my favorites of the challenge.</td>', 'You captured the bareness of the scene so well, congrats!  I''m giving it a good score but would have been higher if you either cropped the moon out or used a cutout to reduce the exposure time on it.  Regardless, this is one of my favorites of the challenge.', '2007-12-20 14:46:23.000000', NULL, 1),
(4326338, 623685, 23487, '<td valign="top">I really like the reflection and the buildings in the background.  Great composition.</td>', 'I really like the reflection and the buildings in the background.  Great composition.', '2007-12-20 14:59:26.000000', NULL, 1),
(4326344, 623864, 23487, '<td valign="top">I wish there was a bit more going on (perhaps more subject matter in the foreground?), but I do like the framing of the waterfall/rocks by the tree on the right.  Well done.</td>', 'I wish there was a bit more going on (perhaps more subject matter in the foreground?), but I do like the framing of the waterfall/rocks by the tree on the right.  Well done.', '2007-12-20 15:01:03.000000', NULL, 1),
(4326345, 622592, 23487, '<td valign="top">Neat shapes!</td>', 'Neat shapes!', '2007-12-20 15:01:25.000000', NULL, 1),
(4326348, 623830, 23487, '<td valign="top">Nice use of space.  Makes my eyes go all the way to the top of the page.  Although it would''ve been hard to do in basic editing without blowing out the lights, I would''ve like to have seen more of the shape of the house and tree.</td>', 'Nice use of space.  Makes my eyes go all the way to the top of the page.  Although it would''ve been hard to do in basic editing without blowing out the lights, I would''ve like to have seen more of the shape of the house and tree.', '2007-12-20 15:02:37.000000', NULL, 1),
(4326370, 623322, 23487, '<td valign="top">Pittsburgh?  Nice exposure.</td>', 'Pittsburgh?  Nice exposure.', '2007-12-20 15:12:08.000000', NULL, 1),
(4326374, 623231, 23487, '<td valign="top">The horizon is bothering me... the picture is perfect: great colors, sharpness, subjects, etc, but that horizon.</td>', 'The horizon is bothering me... the picture is perfect: great colors, sharpness, subjects, etc, but that horizon.', '2007-12-20 15:14:19.000000', NULL, 1),
(4326382, 623775, 67237, '<td valign="top">beautifull image</td>', 'beautifull image', '2007-12-20 15:19:03.000000', NULL, 1),
(4326383, 623529, 67237, '<td valign="top">wow!!..this must be terrific at a larger size</td>', 'wow!!..this must be terrific at a larger size', '2007-12-20 15:19:09.000000', NULL, 1),
(4326386, 622382, 67237, '<td valign="top">This looks like a Saberi''s painting with light kind of shot.<br/>I like the creativity and execution of this image. Definitely a ribbon candidate.</td>', 'This looks like a Saberi''s painting with light kind of shot.I like the creativity and execution of this image. Definitely a ribbon candidate.', '2007-12-20 15:19:44.000000', NULL, 1),
(4326387, 623373, 23487, '<td valign="top">Really cool.  I missed out submitting my own picture for this contest, but I think your''s would''ve beaten mine.  Fun, too.</td>', 'Really cool.  I missed out submitting my own picture for this contest, but I think your''s would''ve beaten mine.  Fun, too.', '2007-12-20 15:19:44.000000', NULL, 1),
(4326388, 623709, 67237, '<td valign="top">serious contender in this challenge..excellent capture..too bad there is a distracting black and orange "something" on the left side..what is it?</td>', 'serious contender in this challenge..excellent capture..too bad there is a distracting black and orange "something" on the left side..what is it?', '2007-12-20 15:20:05.000000', NULL, 1),
(4326389, 623186, 67237, '<td valign="top">beautifull complementary colors here...</td>', 'beautifull complementary colors here...', '2007-12-20 15:20:09.000000', NULL, 1),
(4326390, 623792, 67237, '<td valign="top">nice image of a beautifull subject</td>', 'nice image of a beautifull subject', '2007-12-20 15:20:12.000000', NULL, 1),
(4326391, 623666, 67237, '<td valign="top">nice composition..I like the retro look of it.</td>', 'nice composition..I like the retro look of it.', '2007-12-20 15:20:26.000000', NULL, 1),
(4326392, 623699, 67237, '<td valign="top">the wow of this subject is starting to fade...nice photo though!!</td>', 'the wow of this subject is starting to fade...nice photo though!!', '2007-12-20 15:20:32.000000', NULL, 1),
(4326393, 623463, 67237, '<td valign="top">beautiful composition..the dramatic effect would have more impacct with a foggier look or a little more softness in the upper part.</td>', 'beautiful composition..the dramatic effect would have more impacct with a foggier look or a little more softness in the upper part.', '2007-12-20 15:20:36.000000', NULL, 1),
(4326401, 623576, 54878, '<td valign="top">Of all the moving traffic pictures this is the best one, an interesting take on the subject.</td>', 'Of all the moving traffic pictures this is the best one, an interesting take on the subject.', '2007-12-20 15:24:13.000000', NULL, 1),
(4326425, 623325, 73063, '<td valign="top">Fantastic, feels so peacefull.</td>', 'Fantastic, feels so peacefull.', '2007-12-20 15:38:52.000000', NULL, 1),
(4326427, 623608, 73063, '<td valign="top">Superb! Love the moon shadow, feels extra-terestrial.</td>', 'Superb! Love the moon shadow, feels extra-terestrial.', '2007-12-20 15:40:17.000000', NULL, 1),
(4326441, 623708, 38930, '<td valign="top">This is prety cool</td>', 'This is prety cool', '2007-12-20 15:48:37.000000', NULL, 1),
(4326443, 623847, 38930, '<td valign="top">That''s nice of yourself :)</td>', 'That''s nice of yourself :)', '2007-12-20 15:48:55.000000', NULL, 1),
(4326445, 623029, 38930, '<td valign="top">That moon is intense!  It''s casting a shadow from the house.  A little trick I''ve learned for shots like these is to wave your hand in front of the right part of the lens.  It will block some of the light from the moon, but still give it a nice transition, as opposed to just keeping your hand there, which would cause a harsh line.</td>', 'That moon is intense!  It''s casting a shadow from the house.  A little trick I''ve learned for shots like these is to wave your hand in front of the right part of the lens.  It will block some of the light from the moon, but still give it a nice transition, as opposed to just keeping your hand there, which would cause a harsh line.', '2007-12-20 15:51:13.000000', NULL, 1),
(4326462, 623842, 38930, '<td valign="top">Wow...it must''ve been really dark</td>', 'Wow...it must''ve been really dark', '2007-12-20 16:00:40.000000', NULL, 1),
(4326463, 622537, 38930, '<td valign="top">nice Hummer</td>', 'nice Hummer', '2007-12-20 16:01:28.000000', NULL, 1),
(4326476, 623772, 62671, '<td valign="top">There is an interesting story here, but I feel the filter effects have been over done on it.  I just don''t feel it fits this image.</td>', 'There is an interesting story here, but I feel the filter effects have been over done on it.  I just don''t feel it fits this image.', '2007-12-20 16:11:17.000000', NULL, 1),
(4326506, 623620, 69646, '<td valign="top">great shot, to bad it isnt in focus</td>', 'great shot, to bad it isnt in focus', '2007-12-20 16:29:29.000000', NULL, 1),
(4326507, 622746, 69646, '<td valign="top">cool idea!</td>', 'cool idea!', '2007-12-20 16:29:48.000000', NULL, 1),
(4326511, 623756, 69646, '<td valign="top">a little dark</td>', 'a little dark', '2007-12-20 16:30:40.000000', NULL, 1),
(4326623, 623620, 52450, '<td valign="top">Could it be that it is out of focus?<br/>But it''s really beautiful shot.</td>', 'Could it be that it is out of focus?But it''s really beautiful shot.', '2007-12-20 17:27:16.000000', NULL, 1),
(4326647, 622745, 19831, '<td valign="top">Wowsers! This is one of the coolest fireworks shot I''ve seen. good job on exposure. You''ve got great context, and strong leading lines and a good composition. Nice job!</td>', 'Wowsers! This is one of the coolest fireworks shot I''ve seen. good job on exposure. You''ve got great context, and strong leading lines and a good composition. Nice job!', '2007-12-20 17:46:40.000000', NULL, 1),
(4326671, 622609, 87748, '<td valign="top">Nice effect, but the rest of the scene is too dark.</td>', 'Nice effect, but the rest of the scene is too dark.', '2007-12-20 18:17:11.000000', NULL, 1),
(4326673, 622569, 87748, '<td valign="top">Can''t find a focal point.  Inconsistent detail in the movements... the two on the left are indescribable but the one on the right is easily seen.</td>', 'Can''t find a focal point.  Inconsistent detail in the movements... the two on the left are indescribable but the one on the right is easily seen.', '2007-12-20 18:18:55.000000', NULL, 1),
(4326676, 622447, 87748, '<td valign="top">Room is lit by the tree.  A good idea.  Lighting doesn''t seem sufficient, though, and the color cast is a little murky (maybe white balance issue).</td>', 'Room is lit by the tree.  A good idea.  Lighting doesn''t seem sufficient, though, and the color cast is a little murky (maybe white balance issue).', '2007-12-20 18:19:50.000000', NULL, 1),
(4326677, 623752, 87748, '<td valign="top">If you''re trying to emphasize "fast" here, then you''ve got a starting point.  My eye isn''t drawn to the blurring of the cars (alluding to "fast"), so the image loses a lot of potential.  A focal point in long exposures seems to be hard, and I can''t really find one here.</td>', 'If you''re trying to emphasize "fast" here, then you''ve got a starting point.  My eye isn''t drawn to the blurring of the cars (alluding to "fast"), so the image loses a lot of potential.  A focal point in long exposures seems to be hard, and I can''t really find one here.', '2007-12-20 18:21:11.000000', NULL, 1),
(4326679, 623855, 87748, '<td valign="top">Pretty nice effect, but it''s very static and uniform in detail.  "One dimensional," so it''s hard for this to compete with most of the other shots.</td>', 'Pretty nice effect, but it''s very static and uniform in detail.  "One dimensional," so it''s hard for this to compete with most of the other shots.', '2007-12-20 18:21:57.000000', NULL, 1),
(4326681, 622264, 87748, '<td valign="top">Night photography and astrophotography are really hard.  Good start here, but there is some discrepancy about whether you want the terrain illuminated or not.  If so, there isn''t enough detail on the terrain.  Sky looks okay, but overall, the image has a lot of noise.</td>', 'Night photography and astrophotography are really hard.  Good start here, but there is some discrepancy about whether you want the terrain illuminated or not.  If so, there isn''t enough detail on the terrain.  Sky looks okay, but overall, the image has a lot of noise.', '2007-12-20 18:23:13.000000', NULL, 1),
(4326682, 623068, 87748, '<td valign="top">This is probably a long exposure, but it cannot be easily seen from the composition of this image (other than all of the lights being illuminated).  A focal point is present: good.</td>', 'This is probably a long exposure, but it cannot be easily seen from the composition of this image (other than all of the lights being illuminated).  A focal point is present: good.', '2007-12-20 18:24:43.000000', NULL, 1),
(4326685, 623756, 87748, '<td valign="top">There needs to be a balance of lighting; from far away this just looks like specks of light on black.  There needs to be a prominent structure (such as the tree) that the eye is drawn to, and it needs to have sufficient lighting.</td>', 'There needs to be a balance of lighting; from far away this just looks like specks of light on black.  There needs to be a prominent structure (such as the tree) that the eye is drawn to, and it needs to have sufficient lighting.', '2007-12-20 18:25:47.000000', NULL, 1),
(4326687, 623208, 87748, '<td valign="top">A basic long exposure here, with hand-held shake artifacts, but it falls in line with the title.  Too many other photos in this challenge that have a lot of detail; this one doesn''t have very much.</td>', 'A basic long exposure here, with hand-held shake artifacts, but it falls in line with the title.  Too many other photos in this challenge that have a lot of detail; this one doesn''t have very much.', '2007-12-20 18:26:43.000000', NULL, 1),
(4326689, 622260, 87748, '<td valign="top">The city is overwhelmed by the light from the cars and the very bright tree.  Perhaps you should have had a larger clearing to see the city, or backed down on the exposure a bit to allow the city lights to be more prominent.</td>', 'The city is overwhelmed by the light from the cars and the very bright tree.  Perhaps you should have had a larger clearing to see the city, or backed down on the exposure a bit to allow the city lights to be more prominent.', '2007-12-20 18:27:33.000000', NULL, 1),
(4326691, 623042, 38930, '<td valign="top">Great concept</td>', 'Great concept', '2007-12-20 18:28:12.000000', NULL, 1),
(4326692, 622777, 87748, '<td valign="top">Looks like an ornament lit by a tree light.  I can see a spinning effect, but there isn''t much detail in this image.  Missing some contrast here, nice idea though.</td>', 'Looks like an ornament lit by a tree light.  I can see a spinning effect, but there isn''t much detail in this image.  Missing some contrast here, nice idea though.', '2007-12-20 18:28:28.000000', NULL, 1),
(4326694, 623184, 38930, '<td valign="top">wow.  one of the best so far</td>', 'wow.  one of the best so far', '2007-12-20 18:29:44.000000', NULL, 1),
(4326695, 623339, 87748, '<td valign="top">This is really a great image.  The clouds billowing over the landmass in the distance is pretty awesome.  I like the colors here.  Only complaint is the darkness near the bottom... just a tad too dark.</td>', 'This is really a great image.  The clouds billowing over the landmass in the distance is pretty awesome.  I like the colors here.  Only complaint is the darkness near the bottom... just a tad too dark.', '2007-12-20 18:29:45.000000', NULL, 1),
(4326697, 623785, 87748, '<td valign="top">Nice long exposure on the water.  A good amount of detail preserved in the rocks, and lighthouse in the distance is a plus.  Too much of a blue cast, in my opinion.  It drowns out the greens a little too much, and that sort of contrast would have helped a little.</td>', 'Nice long exposure on the water.  A good amount of detail preserved in the rocks, and lighthouse in the distance is a plus.  Too much of a blue cast, in my opinion.  It drowns out the greens a little too much, and that sort of contrast would have helped a little.', '2007-12-20 18:30:45.000000', NULL, 1),
(4326699, 623029, 87748, '<td valign="top">Stunning image.  Lots of tension here, which I always like.  Trying to think of someway to put the building out of the center of the image, but that would take away the effect.  White on the right is a bit overwhelming, but I think it actually adds to the effect here.</td>', 'Stunning image.  Lots of tension here, which I always like.  Trying to think of someway to put the building out of the center of the image, but that would take away the effect.  White on the right is a bit overwhelming, but I think it actually adds to the effect here.', '2007-12-20 18:31:49.000000', NULL, 1),
(4326701, 622417, 87748, '<td valign="top">Simple image.  Water seems to be foaming (like fog).  Rocks need a little more detail (light), but other than that, this is great.</td>', 'Simple image.  Water seems to be foaming (like fog).  Rocks need a little more detail (light), but other than that, this is great.', '2007-12-20 18:32:31.000000', NULL, 1),
(4326703, 623688, 87748, '<td valign="top">The texture caused by the water flowing back out at the bottom absolutely makes this image for me.  Wish there was a different sky, with more textured clouds, but you work with what you have.  Pretty good!</td>', 'The texture caused by the water flowing back out at the bottom absolutely makes this image for me.  Wish there was a different sky, with more textured clouds, but you work with what you have.  Pretty good!', '2007-12-20 18:34:15.000000', NULL, 1),
(4326704, 623775, 87748, '<td valign="top">Absolutely great balance of light and texture in the dark spots.  The rocks could have easily been blacked-out by the sun, but you didn''t allow that here.  Great water effect, great sky, while preserving detail on the rocks!</td>', 'Absolutely great balance of light and texture in the dark spots.  The rocks could have easily been blacked-out by the sun, but you didn''t allow that here.  Great water effect, great sky, while preserving detail on the rocks!', '2007-12-20 18:35:14.000000', NULL, 1),
(4326707, 621993, 87748, '<td valign="top">Just a tad too dark for my liking, but I still like it.  I like the red color cast on the water.  Moon is a plus... adds something extra to a patch of sky that would otherwise be just blue.  Could do without the lights on the left side, though.</td>', 'Just a tad too dark for my liking, but I still like it.  I like the red color cast on the water.  Moon is a plus... adds something extra to a patch of sky that would otherwise be just blue.  Could do without the lights on the left side, though.', '2007-12-20 18:36:31.000000', NULL, 1),
(4326709, 623377, 87748, '<td valign="top">Pretty nice capture here.  Colors are great, balance of light is great, and the activity in the photo is great.  Image almost seems alive.</td>', 'Pretty nice capture here.  Colors are great, balance of light is great, and the activity in the photo is great.  Image almost seems alive.', '2007-12-20 18:38:09.000000', NULL, 1),
(4326724, 623459, 87748, '<td valign="top">Wish there was more light balance here; the rocks are blacked-out.</td>', 'Wish there was more light balance here; the rocks are blacked-out.', '2007-12-20 18:43:40.000000', NULL, 1),
(4326726, 623709, 87748, '<td valign="top">Nice capture... especially getting the flowing motion of the water and keeping the subject sharp.</td>', 'Nice capture... especially getting the flowing motion of the water and keeping the subject sharp.', '2007-12-20 18:44:15.000000', NULL, 1),
(4326729, 623186, 87748, '<td valign="top">Orange color cast is a little too strong here for my liking.  Good detail retained on teh rocks, and the clouds are pretty neat.</td>', 'Orange color cast is a little too strong here for my liking.  Good detail retained on teh rocks, and the clouds are pretty neat.', '2007-12-20 18:45:37.000000', NULL, 1),
(4326733, 623543, 87748, '<td valign="top">Great city shot.  Feels like a bit of an unusual angle, but that doesn''t detract from the overall image.  Nice bit of light still retained in the sky.</td>', 'Great city shot.  Feels like a bit of an unusual angle, but that doesn''t detract from the overall image.  Nice bit of light still retained in the sky.', '2007-12-20 18:47:13.000000', NULL, 1),
(4326743, 623792, 87748, '<td valign="top">Image is a little uneventful.  Good snap of the opera house, and nice lighting towards the right side.</td>', 'Image is a little uneventful.  Good snap of the opera house, and nice lighting towards the right side.', '2007-12-20 18:49:59.000000', NULL, 1),
(4326744, 622786, 87748, '<td valign="top">Out-of-focus person is a little distracting.  Good detail on the rocks and skyline, and a good amount (if a little too much) light.</td>', 'Out-of-focus person is a little distracting.  Good detail on the rocks and skyline, and a good amount (if a little too much) light.', '2007-12-20 18:50:37.000000', NULL, 1),
(4326746, 623184, 87748, '<td valign="top">Seems to be composed well, but the landscape is too dark for my liking.</td>', 'Seems to be composed well, but the landscape is too dark for my liking.', '2007-12-20 18:52:45.000000', NULL, 1),
(4326747, 623871, 87748, '<td valign="top">Pretty good balance of light (still a tad to dark).  Too much here, though, there isn''t a focal point.  Red lights near the tree line are a little distracting.</td>', 'Pretty good balance of light (still a tad to dark).  Too much here, though, there isn''t a focal point.  Red lights near the tree line are a little distracting.', '2007-12-20 18:53:37.000000', NULL, 1),
(4326750, 623130, 87748, '<td valign="top">Absolutely great light balance.  There is too much here, especially with the trees in the foreground.  Coming a little close to the bridge and a slightly different angle probably would''ve helped.</td>', 'Absolutely great light balance.  There is too much here, especially with the trees in the foreground.  Coming a little close to the bridge and a slightly different angle probably would''ve helped.', '2007-12-20 18:55:10.000000', NULL, 1),
(4326751, 622085, 87748, '<td valign="top">Good light balance.  Image is a little murky.  Long exposure here seems to be to achieve adequate light instead of enhancing an effect.  No focal point.</td>', 'Good light balance.  Image is a little murky.  Long exposure here seems to be to achieve adequate light instead of enhancing an effect.  No focal point.', '2007-12-20 18:56:00.000000', NULL, 1),
(4326754, 623252, 87748, '<td valign="top">I can definitely see the "rush" in the cars, and a little in the pedestrians.  Need more light on the right side, though.</td>', 'I can definitely see the "rush" in the cars, and a little in the pedestrians.  Need more light on the right side, though.', '2007-12-20 18:57:02.000000', NULL, 1),
(4326755, 622730, 87748, '<td valign="top">Good composure.  A little too dark, but not by much.  Nice orange cast on the water.</td>', 'Good composure.  A little too dark, but not by much.  Nice orange cast on the water.', '2007-12-20 18:57:33.000000', NULL, 1),
(4326756, 623463, 87748, '<td valign="top">Good light balance.  Subject sticks out from the rest of the image a bit. Good angle.</td>', 'Good light balance.  Subject sticks out from the rest of the image a bit. Good angle.', '2007-12-20 18:58:37.000000', NULL, 1),
(4326758, 622229, 87748, '<td valign="top">Whole composure is a little too blurred.  Ocean seems to be one big, blue cloud.  Rocks are either out of focus or movement has occurred during exposure.  Try a slightly faster shutter speed so you can see movement and texture in the water.</td>', 'Whole composure is a little too blurred.  Ocean seems to be one big, blue cloud.  Rocks are either out of focus or movement has occurred during exposure.  Try a slightly faster shutter speed so you can see movement and texture in the water.', '2007-12-20 19:00:07.000000', NULL, 1),
(4326763, 623790, 87748, '<td valign="top">Ornament is a little under-lit; lights in the background are a little over-exposed.  Some assisted lighting on the ornament and a slightly faster shutter speed would''ve made this a great capture.</td>', 'Ornament is a little under-lit; lights in the background are a little over-exposed.  Some assisted lighting on the ornament and a slightly faster shutter speed would''ve made this a great capture.', '2007-12-20 19:01:31.000000', NULL, 1),
(4326765, 623376, 87748, '<td valign="top">Good light balance, and the color is pretty nice.  Would''ve liked some other colors in addition to the orange and gray/mist here.</td>', 'Good light balance, and the color is pretty nice.  Would''ve liked some other colors in addition to the orange and gray/mist here.', '2007-12-20 19:02:39.000000', NULL, 1),
(4326768, 621985, 87748, '<td valign="top">Lightning shots always deserve some admiration, in my opinion, due to their fleeting nature.  The lighting extends outside of the composure here, which isn''t too terribly bad.  Rest of scene is really dark.</td>', 'Lightning shots always deserve some admiration, in my opinion, due to their fleeting nature.  The lighting extends outside of the composure here, which isn''t too terribly bad.  Rest of scene is really dark.', '2007-12-20 19:04:01.000000', NULL, 1),
