(4328096, 623543, 49109, '<td valign="top">very well exposed, good composition and sharpness</td>', 'very well exposed, good composition and sharpness', '2007-12-21 11:59:40.000000', NULL, 1),
(4328100, 623620, 88010, '<td valign="top">Nice capture</td>', 'Nice capture', '2007-12-21 12:00:29.000000', NULL, 1),
