(4328107, 623500, 88010, '<td valign="top">That''s cool, a monorail trail of lights .</td>', 'That''s cool, a monorail trail of lights .', '2007-12-21 12:01:51.000000', NULL, 1),
(4328109, 623752, 88010, '<td valign="top">Very clever use on words</td>', 'Very clever use on words', '2007-12-21 12:02:10.000000', NULL, 1),
(4328110, 623029, 49109, '<td valign="top">beautiful location and color. moon is a tad too bright, composition is too centered</td>', 'beautiful location and color. moon is a tad too bright, composition is too centered', '2007-12-21 12:02:24.000000', NULL, 1),
(4328114, 623514, 49109, '<td valign="top">good perspective and timing. a tad overexposed.</td>', 'good perspective and timing. a tad overexposed.', '2007-12-21 12:03:35.000000', NULL, 1),
(4328116, 623541, 49109, '<td valign="top">good perspective and exposure. crop is a bit tight at right</td>', 'good perspective and exposure. crop is a bit tight at right', '2007-12-21 12:04:37.000000', NULL, 1),
(4328120, 622537, 49109, '<td valign="top">a very well matching subject from a well chosen POV. a bit much of a border, especially at the bottom.</td>', 'a very well matching subject from a well chosen POV. a bit much of a border, especially at the bottom.', '2007-12-21 12:06:10.000000', NULL, 1),
(4328124, 623855, 49109, '<td valign="top">very nice and colorful abstract</td>', 'very nice and colorful abstract', '2007-12-21 12:06:31.000000', NULL, 1),
(4328130, 622316, 49109, '<td valign="top">good POV and exposure. colors are too warm IMHO</td>', 'good POV and exposure. colors are too warm IMHO', '2007-12-21 12:07:12.000000', NULL, 1),
(4328140, 622786, 49109, '<td valign="top">this would have worked much better in landscape orientation and from a slightly lower POV. it seems to me that there is too much of the river and sky to be seen, while the person is crammed into the corner.</td>', 'this would have worked much better in landscape orientation and from a slightly lower POV. it seems to me that there is too much of the river and sky to be seen, while the person is crammed into the corner.', '2007-12-21 12:08:56.000000', NULL, 1),
(4328149, 623339, 49109, '<td valign="top">nice scenery, good focus. overall a bit pale, wished for more contrast. really like the huge cloud behind the island</td>', 'nice scenery, good focus. overall a bit pale, wished for more contrast. really like the huge cloud behind the island', '2007-12-21 12:10:56.000000', NULL, 1),
(4328154, 622715, 49109, '<td valign="top">very interesting play of light here. sky color looks a bit off, had pushed the blues a bit</td>', 'very interesting play of light here. sky color looks a bit off, had pushed the blues a bit', '2007-12-21 12:12:45.000000', NULL, 1),
(4328158, 622191, 49109, '<td valign="top">well composed shot, good exposure. had adjusted white balance a bit to get a richer sky color</td>', 'well composed shot, good exposure. had adjusted white balance a bit to get a richer sky color', '2007-12-21 12:13:51.000000', NULL, 1),
(4328163, 622382, 49109, '<td valign="top">nice concept, good tones. bright light and spots at top are distracting and should have been cropped off IMO</td>', 'nice concept, good tones. bright light and spots at top are distracting and should have been cropped off IMO', '2007-12-21 12:15:30.000000', NULL, 1),
(4328233, 623279, 30049, '<td valign="top">At first glance I didn''t notice that this was an evening shot.  The lights in the background didn''t register at first to what they were, then after that I noticed the stars in the evening sky.  I hope that others'' are slowing down enough to catch the fine details.  Good luck.</td>', 'At first glance I didn''t notice that this was an evening shot.  The lights in the background didn''t register at first to what they were, then after that I noticed the stars in the evening sky.  I hope that others'' are slowing down enough to catch the fine details.  Good luck.', '2007-12-21 12:51:13.000000', NULL, 1),
(4328235, 623863, 30049, '<td valign="top">Wow.  The B&amp;W treatment, plus the non-descript houses (no cars in sight), give this photo a nostalgic feel.  It would difficult to put an age on this if this photo was just presented to someone randomly.  Kinda cool.  :-)  Good luck in the challenge.</td>', 'Wow.  The B&W treatment, plus the non-descript houses (no cars in sight), give this photo a nostalgic feel.  It would difficult to put an age on this if this photo was just presented to someone randomly.  Kinda cool.  :-)  Good luck in the challenge.', '2007-12-21 12:53:02.000000', NULL, 1),
(4328238, 623680, 30049, '<td valign="top">Very interesting abstract!  I like it.</td>', 'Very interesting abstract!  I like it.', '2007-12-21 12:54:07.000000', NULL, 1),
(4328242, 623873, 30049, '<td valign="top">The lighting is cool, not really digging the toy car however.  A glass globe, a half-full wine glass...anything...may have been more artistic and interesting.  JMO of course.  Good luck in the challenge.</td>', 'The lighting is cool, not really digging the toy car however.  A glass globe, a half-full wine glass...anything...may have been more artistic and interesting.  JMO of course.  Good luck in the challenge.', '2007-12-21 12:55:29.000000', NULL, 1),
(4328246, 623212, 30049, '<td valign="top">This is a fun shot.  Great idea and pretty good execution of the capture.  I like how you can see the snow falling in the dark sky area.  Well done!</td>', 'This is a fun shot.  Great idea and pretty good execution of the capture.  I like how you can see the snow falling in the dark sky area.  Well done!', '2007-12-21 12:56:32.000000', NULL, 1),
(4328250, 623839, 30049, '<td valign="top">That tree looks delightful with the snow on the lights.  Nice catch!</td>', 'That tree looks delightful with the snow on the lights.  Nice catch!', '2007-12-21 12:58:11.000000', NULL, 1),
(4328252, 623610, 30049, '<td valign="top">Very nice.  Good choice for B&amp;W...like how you''ve caught the snow coming down.</td>', 'Very nice.  Good choice for B&W...like how you''ve caught the snow coming down.', '2007-12-21 12:59:46.000000', NULL, 1),
(4328259, 622939, 30049, '<td valign="top">It''s "ok".  Not very much exciting to look at regarding a subject IMO.  Might see more detail if the image was using the maximum 640 pixels allowed.  I do have to say that even at this smaller size I can make out some nice detail in the glow of the coals.  All JMO of course.  Good luck in the challenge.</td>', 'It''s "ok".  Not very much exciting to look at regarding a subject IMO.  Might see more detail if the image was using the maximum 640 pixels allowed.  I do have to say that even at this smaller size I can make out some nice detail in the glow of the coals.  All JMO of course.  Good luck in the challenge.', '2007-12-21 13:02:10.000000', NULL, 1),
(4328278, 623664, 30049, '<td valign="top">Looks like an experiment in lighting, kinda fun, but I''m not sure that it''s going to be met with much enthusiasm in the challenge.  Of course I''ve been wrong before.  :-P  Good luck.</td>', 'Looks like an experiment in lighting, kinda fun, but I''m not sure that it''s going to be met with much enthusiasm in the challenge.  Of course I''ve been wrong before.  :-P  Good luck.', '2007-12-21 13:10:51.000000', NULL, 1),
(4328282, 623852, 30049, '<td valign="top">I like the water and the light reflection on the water - that''s cool.  I do wish the composition had more room at the top for the lighthouse.  It''s tight, needs another 20-40 pixels at least IMO.  Sky seems a little grainy also...  All JMO of course.  :-)  Good luck in the challenge.</td>', 'I like the water and the light reflection on the water - that''s cool.  I do wish the composition had more room at the top for the lighthouse.  It''s tight, needs another 20-40 pixels at least IMO.  Sky seems a little grainy also...  All JMO of course.  :-)  Good luck in the challenge.', '2007-12-21 13:12:47.000000', NULL, 1),
(4328284, 622316, 30049, '<td valign="top">You picked a good time of day to shoot this.  The color in the sky complements the street lighting and gives this some balance.</td>', 'You picked a good time of day to shoot this.  The color in the sky complements the street lighting and gives this some balance.', '2007-12-21 13:13:30.000000', NULL, 1),
(4328288, 623481, 30049, '<td valign="top">Nice use of negative space, and I like the color from the setting sun.  Well done!</td>', 'Nice use of negative space, and I like the color from the setting sun.  Well done!', '2007-12-21 13:14:32.000000', NULL, 1),
(4328289, 622417, 30049, '<td valign="top">This would make a nice print.  I like the simplicity of it.  Very zenlike.  :-)  Good luck in the challenge.</td>', 'This would make a nice print.  I like the simplicity of it.  Very zenlike.  :-)  Good luck in the challenge.', '2007-12-21 13:14:58.000000', NULL, 1),
(4328318, 622160, 55117, '<td valign="top">Very pretty, if somewhat generic.</td>', 'Very pretty, if somewhat generic.', '2007-12-21 13:27:39.000000', NULL, 1),
(4328321, 623753, 55117, '<td valign="top">Very safe shot. Traditional "water n'' rocks" approach to long exposure. Good composition.</td>', 'Very safe shot. Traditional "water n'' rocks" approach to long exposure. Good composition.', '2007-12-21 13:28:46.000000', NULL, 1),
(4328322, 623558, 55117, '<td valign="top">Snazzy.</td>', 'Snazzy.', '2007-12-21 13:29:11.000000', NULL, 1),
(4328324, 622382, 55117, '<td valign="top">Excellent and creative use of lighting. Composition is superb.</td>', 'Excellent and creative use of lighting. Composition is superb.', '2007-12-21 13:29:46.000000', NULL, 1),
(4328326, 623876, 55117, '<td valign="top">Love the colors. A bit put-off by the softness. Was this on a tripod?</td>', 'Love the colors. A bit put-off by the softness. Was this on a tripod?', '2007-12-21 13:30:14.000000', NULL, 1),
(4328328, 623838, 55117, '<td valign="top">Love the composition and colors. Exquisite.</td>', 'Love the composition and colors. Exquisite.', '2007-12-21 13:30:30.000000', NULL, 1),
(4328329, 623680, 55117, '<td valign="top">I don''t know why, but I like.</td>', 'I don''t know why, but I like.', '2007-12-21 13:30:47.000000', NULL, 1),
(4328331, 623673, 55117, '<td valign="top">Dull. Nice concept, but practically no contrast, and boring composition. Try post-processing and pre-planning next time.</td>', 'Dull. Nice concept, but practically no contrast, and boring composition. Try post-processing and pre-planning next time.', '2007-12-21 13:31:40.000000', NULL, 1),
