(4334691, 623380, 70036, '<td valign="top">Stunning.  Great composition, color, exposure.</td>', 'Stunning.  Great composition, color, exposure.', '2007-12-25 19:14:09.000000', NULL, 1),
(4334694, 623459, 70036, '<td valign="top">To my eye the sunset keeps me from seeing the detail in the foreground.  This shot was begging for a graduated ND filter.  It would be nice to see this edited using all the tools to bring out what appears to be a spectacular foreground.</td>', 'To my eye the sunset keeps me from seeing the detail in the foreground.  This shot was begging for a graduated ND filter.  It would be nice to see this edited using all the tools to bring out what appears to be a spectacular foreground.', '2007-12-25 19:16:41.000000', NULL, 1),
